#include <stdint.h>
#include <stdatomic.h>

_Static_assert(sizeof(uint32_t) == 4, "32-bit counter required");
static _Atomic uint32_t counter = 0;

typedef struct Result {
    uint32_t previous;
    uint32_t current;
} Result;

Result increment(uint32_t amount) {
    uint32_t previous = atomic_fetch_add(&counter, amount);
    return (Result){ .previous = previous, .current = previous + amount };
}

typedef struct Point {
    double x;
    double y;
} Point;

static Point translate(Point value, double dx, double dy) {
    return (Point){ .x = value.x + dx, .y = value.y + dy };
}

double length_squared(const Point *point) {
    return point->x * point->x + point->y * point->y;
}
